import{_ as t,c as o,o as r,ae as i}from"./chunks/framework.CFeneB-q.js";const h=JSON.parse('{"title":"PC · Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/pc/introduction.md","filePath":"en/pc/introduction.md","lastUpdated":1789438865000}'),a={name:"en/pc/introduction.md"};function d(n,e,s,c,l,u){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="pc-·-introduction" tabindex="-1">PC · Introduction <a class="header-anchor" href="#pc-·-introduction" aria-label="Permalink to &quot;PC · Introduction&quot;">​</a></h1><h2 id="platform-overview" tabindex="-1">Platform overview <a class="header-anchor" href="#platform-overview" aria-label="Permalink to &quot;Platform overview&quot;">​</a></h2><p>E9 Delivery Platform / Keystone 2.0 is a <strong>one-codebase, multi-customer-delivery</strong> construction-site information management front-end: business domains cover personnel, quality, safety, machinery, general management, material cost, progress collaboration and environment management, plus a data dashboard (screen) subsystem. Front-ends are delivered per customer as &quot;standard product + customer copies&quot;, with business views trimmed at compile time.</p><h2 id="multi-customer-delivery-model" tabindex="-1">Multi-customer delivery model <a class="header-anchor" href="#multi-customer-delivery-model" aria-label="Permalink to &quot;Multi-customer delivery model&quot;">​</a></h2><p>Two mechanisms combined:</p><ol><li><strong>Compile-time view trimming</strong>: <code>pnpm start</code> interactively selects which business views participate in compilation, writing <code>VITE_BUILD_VIEWS</code> into <code>.env.&lt;mode&gt;</code> (aliases such as <code>fc,pzgc,st,cl</code>). The single source of alias mapping is <code>src/config/business.config.js</code> (fanchang=fc, pzgc, shate=st, changliu=cl, test=ts; keystone is the default business, always included).</li><li><strong>One repository copy per customer</strong>: 20+ <code>*-deliver-ui / *-delivery-ui</code> repositories under the e9tech workspace, customized and maintained per customer.</li></ol><h2 id="project-family" tabindex="-1">Project family <a class="header-anchor" href="#project-family" aria-label="Permalink to &quot;Project family&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project</th><th>Stack</th><th>Role</th><th>Status</th></tr></thead><tbody><tr><td><code>e9tech/keystone-deliver-ui</code></td><td>Vue 3.3 + Vite 4 + Pinia + i18next + Arco</td><td><strong>Standard product</strong> (carries the multi-customer mechanism; quick-start blueprint of this guide)</td><td>Mainline</td></tr><tr><td><code>e9tech/e9-delivery-ui</code></td><td>Vue 3.3 + Vite 4 + Pinia + vue-i18n + Arco</td><td>New base (no multi-business trimming; flat <code>views/backstage</code> structure)</td><td>Maintained</td></tr><tr><td>20+ other copies under <code>e9tech/</code> (changliu / demo / fanchang / g108 / nggs / qhgs / runcheng / sa / sate / snyh / st / wlksl / wzzn / zj / zjxy …)</td><td>Same as standard</td><td>Customer-specific delivery copies</td><td>Maintained per copy</td></tr><tr><td><code>admin-app/beam-web</code></td><td>Vue 2.6 + RuoYi + Element UI</td><td>Construction informatization (beam plant / mixing station / dashboards)</td><td>Legacy</td></tr><tr><td><code>admin-app/e9-epim</code></td><td>Vue 2.6 + Element UI + BPMN</td><td>Platform operation console (tenants / approvals / menus)</td><td>Legacy</td></tr><tr><td><code>admin-app/e9-inspection-web</code></td><td>Vue 3.4 + Vite 5 + Element Plus</td><td>Standalone inspection system</td><td>Legacy</td></tr><tr><td><code>admin-app/e9ech</code></td><td>—</td><td>Broken copy of e9tech</td><td><strong>Deprecated, do not reference</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Copy hygiene</p><p>Manual copy directories such as <code>keystone-deliver-ui - 副本</code> exist in the workspace — <strong>never use them as blueprints</strong>. Always work from the <code>keystone-deliver-ui</code> standard repository.</p></div><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Delivery front-end (交付端)</td><td>The customer-delivered PC console — the subject of the PC section</td></tr><tr><td>Operation console (运营端)</td><td>e9-epim, platform-side operations (tenants, approvals, menu config)</td></tr><tr><td>Dashboard (screen)</td><td><code>views/screen/</code> dashboard subsystem with its own router / store / hooks / component library</td></tr><tr><td>SSO</td><td>Single sign-on platform (e9-sso-ui); all ends redirect there to log in</td></tr><tr><td>Tenant (tenantId)</td><td>Multi-customer isolation unit, carried in request headers</td></tr><tr><td>Button permission</td><td>Operation-level permission via the <code>v-permission</code> directive + <code>definePermission</code> codes</td></tr><tr><td>i18n layering</td><td>i18next with preload namespaces (basic_components / common / screen) + route-level lazy loading</td></tr><tr><td><code>VITE_BUILD_VIEWS</code></td><td>Env var controlling which business views are compiled; written by <code>pnpm start</code></td></tr><tr><td><code>switch:api</code></td><td>Script that points requests at a chosen customer&#39;s backend</td></tr></tbody></table><h2 id="reading-path" tabindex="-1">Reading path <a class="header-anchor" href="#reading-path" aria-label="Permalink to &quot;Reading path&quot;">​</a></h2><ul><li><strong>Newcomers</strong>: Introduction → <a href="./technology-stack.html">Technology Stack</a> → <a href="./getting-started.html">Quick Start</a> to run the standard product within half a day; then Project Structure → Feature Development for your first page;</li><li><strong>Troubleshooting</strong>: the six Reference pages (HTTP wrapper, SSO flow, env vars, build &amp; deploy, button-permission architecture, i18n architecture);</li><li>Note the English side of this guide keeps only core pages; for everything else read the Chinese version.</li></ul><hr><p><strong>Owner</strong>: E9 Frontend Team ｜ <strong>Last verified</strong>: 2026-09-16 ｜ <strong>Blueprint</strong>: <code>keystone-deliver-ui</code></p>',15)])])}const p=t(a,[["render",d]]);export{h as __pageData,p as default};
